<?php
$locations=$technology->siteLocations();$links=$technology->connectivityLinks();
$statusClass=fn(string $s)=>match($s){'online'=>'success','warning'=>'warning','offline'=>'danger','planned'=>'secondary','maintenance'=>'info',default=>'secondary'};
$typeLabel=fn(string $t)=>match($t){'main_site'=>'Conjunto / predio','headquarters'=>'Sede principal','guard_post'=>'Garita','park'=>'Parque','common_area'=>'Área común','technical_area'=>'Área técnica','perimeter'=>'Perímetro','remote_point'=>'Punto remoto','building'=>'Edificio','tower'=>'Torre','parking'=>'Estacionamiento',default=>ucfirst(str_replace('_',' ',$t))};
$types=['main_site','headquarters','sector','street','block','parcel','building','tower','floor','unit','guard_post','park','common_area','technical_area','parking','perimeter','remote_point','other'];
?>
<div class="alert alert-primary"><strong>Topología técnica de una sola instalación.</strong> Aquí se dibuja dónde está el servidor principal y cómo llegan las redes a garitas, edificios, parques, cuartos técnicos y puntos remotos. No implica instalar computadoras adicionales.</div>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h5 class="mb-0">Sedes, garitas y ubicaciones técnicas</h5><small class="text-body-secondary"><?=count($locations)?> ubicación(es)</small></div><?php if(can('integrations.manage')):?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#locationModal"><i class="bi bi-plus-lg"></i> Nueva ubicación</button><?php endif;?></div>
<div class="row g-3 mb-4"><?php foreach($locations as $l):?><div class="col-md-6 col-xl-4"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between gap-2"><div><span class="badge text-bg-light border mb-2"><?=e($typeLabel((string)$l['location_type']))?></span><h5 class="mb-1"><?=e($l['name'])?></h5><small class="text-body-secondary"><code><?=e($l['code'])?></code><?=!empty($l['parent_name'])?' · '.e($l['parent_name']):''?></small></div><span class="badge text-bg-<?=e($statusClass((string)$l['status']))?> align-self-start"><?=e(status_label((string)$l['status']))?></span></div><hr><div class="small"><i class="bi bi-diagram-3 me-2"></i><?=e(strtoupper((string)$l['connectivity_mode']))?><?php if(!empty($l['is_operational_center'])):?><span class="badge text-bg-primary ms-2">Servidor principal</span><?php endif;?></div><p class="small text-body-secondary mt-2 mb-3"><?=e($l['notes']??'')?></p><?php if(can('integrations.manage')):?><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-primary flex-grow-1 js-edit-location" data-bs-toggle="modal" data-bs-target="#locationModal" data-json='<?=e(json_encode($l,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>'><i class="bi bi-pencil"></i> Editar</button><form method="post" action="<?=url('site-location-delete')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($l['id'])?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Si tiene dependencias se archivará. ¿Continuar?"><i class="bi bi-trash"></i></button></form></div><?php endif;?></div></div></div><?php endforeach;?><?php if(!$locations):?><div class="col-12"><?=empty_state('Sin ubicaciones técnicas','Crea la sede principal y luego garitas, edificios, cuartos técnicos, parques o puntos remotos.','bi bi-map')?></div><?php endif;?></div>
<div class="card"><div class="card-header d-flex flex-wrap justify-content-between align-items-center gap-2"><div><strong>Enlaces y rutas de comunicación</strong><small class="d-block text-body-secondary">Fibra, UTP, Wi‑Fi, VPN, Internet, red celular o LoRaWAN.</small></div><?php if(can('integrations.manage')):?><button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#linkModal"><i class="bi bi-plus-lg"></i> Nuevo enlace</button><?php endif;?></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Enlace</th><th>Origen</th><th>Destino</th><th>Tecnología</th><th>Función</th><th>Capacidad</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach($links as $l):?><tr><td><strong><?=e($l['name'])?></strong><small class="d-block text-body-secondary"><code><?=e($l['code'])?></code></small></td><td><?=e($l['from_name']??'Externo')?></td><td><?=e($l['to_name']??'Internet / nube')?></td><td><?=e(strtoupper((string)$l['link_type']))?></td><td><?=e(ucfirst((string)$l['link_role']))?></td><td><?=e($l['capacity_label']??'-')?></td><td><span class="badge text-bg-<?=e($statusClass((string)$l['status']))?>"><?=e(status_label((string)$l['status']))?></span></td><td class="text-end text-nowrap"><?php if(can('integrations.manage')):?><button class="btn btn-sm btn-outline-primary js-edit-link" data-bs-toggle="modal" data-bs-target="#linkModal" data-json='<?=e(json_encode($l,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>'><i class="bi bi-pencil"></i></button> <form class="d-inline" method="post" action="<?=url('connectivity-delete')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($l['id'])?>"><button class="btn btn-sm btn-outline-danger" data-confirm="¿Eliminar este enlace?"><i class="bi bi-trash"></i></button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$links):?><tr><td colspan="8" class="text-center py-5 text-body-secondary">No hay enlaces registrados.</td></tr><?php endif;?></tbody></table></div></div></div>
<?php if(can('integrations.manage')):?>
<div class="modal fade" id="locationModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><form method="post" action="<?=url('site-location-save')?>"><?=csrf_field()?><input type="hidden" name="id" id="locationId"><div class="modal-header"><h5 class="modal-title" id="locationTitle">Nueva ubicación técnica</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-4"><label class="form-label">Código</label><input class="form-control" name="code" id="locationCode" required></div><div class="col-md-8"><label class="form-label">Nombre</label><input class="form-control" name="name" id="locationName" required></div><div class="col-md-4"><label class="form-label">Tipo</label><select class="form-select" name="location_type" id="locationType"><?php foreach($types as $type):?><option value="<?=e($type)?>"><?=e($typeLabel($type))?></option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label">Depende de</label><select class="form-select" name="parent_id" id="locationParent"><option value="">Raíz</option><?php foreach($locations as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Conectividad</label><select class="form-select" name="connectivity_mode" id="locationMode"><?php foreach(['lan','fiber','utp','wifi','radio','vpn','internet','cellular','lorawan','mixed','none'] as $m):?><option value="<?=e($m)?>"><?=e(strtoupper($m))?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Estado</label><select class="form-select" name="status" id="locationStatus"><option value="unknown">Desconocido</option><option value="planned">Planificado</option><option value="online">En línea</option><option value="warning">Advertencia</option><option value="offline">Sin conexión</option><option value="maintenance">Mantenimiento</option></select></div><div class="col-md-4"><label class="form-label">Latitud opcional</label><input class="form-control" name="latitude" id="locationLat"></div><div class="col-md-4"><label class="form-label">Longitud opcional</label><input class="form-control" name="longitude" id="locationLng"></div><div class="col-12"><label class="form-check form-switch"><input class="form-check-input" type="checkbox" name="is_operational_center" id="locationCore"><span class="form-check-label">Esta ubicación contiene el servidor principal</span></label></div><div class="col-12"><label class="form-label">Notas</label><textarea class="form-control" name="notes" id="locationNotes" rows="3"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar ubicación</button></div></form></div></div></div>
<div class="modal fade" id="linkModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post" action="<?=url('connectivity-save')?>"><?=csrf_field()?><input type="hidden" name="id" id="linkId"><div class="modal-header"><h5 class="modal-title" id="linkTitle">Nuevo enlace</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-4"><label class="form-label">Código</label><input class="form-control" name="code" id="linkCode" required></div><div class="col-md-8"><label class="form-label">Nombre</label><input class="form-control" name="name" id="linkName" required></div><div class="col-md-6"><label class="form-label">Origen</label><select class="form-select" name="from_location_id" id="linkFrom"><option value="">Externo / proveedor</option><?php foreach($locations as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Destino</label><select class="form-select" name="to_location_id" id="linkTo"><option value="">Internet / nube</option><?php foreach($locations as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Tecnología</label><select class="form-select" name="link_type" id="linkType"><?php foreach(['fiber','utp','wifi','radio','vpn','internet','cellular','lorawan','mixed','other'] as $t):?><option value="<?=e($t)?>"><?=e(strtoupper($t))?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Función</label><select class="form-select" name="link_role" id="linkRole"><option value="primary">Principal</option><option value="backup">Respaldo</option><option value="independent">Independiente</option><option value="iot">IoT</option></select></div><div class="col-md-3"><label class="form-label">Proveedor</label><input class="form-control" name="provider" id="linkProvider"></div><div class="col-md-3"><label class="form-label">Capacidad</label><input class="form-control" name="capacity_label" id="linkCapacity" placeholder="1 Gbps"></div><div class="col-md-4"><label class="form-label">Estado</label><select class="form-select" name="status" id="linkStatus"><option value="unknown">Desconocido</option><option value="planned">Planificado</option><option value="online">En línea</option><option value="warning">Advertencia</option><option value="offline">Sin conexión</option><option value="maintenance">Mantenimiento</option></select></div><div class="col-md-4"><label class="form-check form-switch mt-4"><input class="form-check-input" type="checkbox" name="monitored" id="linkMonitored" checked><span class="form-check-label">Monitorear estado</span></label></div><div class="col-12"><label class="form-label">Notas</label><textarea class="form-control" name="notes" id="linkNotes" rows="2"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar enlace</button></div></form></div></div></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{const lm=document.getElementById('locationModal');lm.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;let d={};if(b&&b.classList.contains('js-edit-location')){try{d=JSON.parse(b.dataset.json||'{}')}catch(x){d={}}}document.getElementById('locationTitle').textContent=d.id?'Editar ubicación':'Nueva ubicación técnica';const map={locationId:'id',locationCode:'code',locationName:'name',locationType:'location_type',locationParent:'parent_id',locationMode:'connectivity_mode',locationStatus:'status',locationLat:'latitude',locationLng:'longitude',locationNotes:'notes'};for(const [el,k] of Object.entries(map))document.getElementById(el).value=d[k]??(el==='locationType'?'headquarters':el==='locationMode'?'lan':el==='locationStatus'?'unknown':'');document.getElementById('locationCore').checked=!!Number(d.is_operational_center||0);});const cm=document.getElementById('linkModal');cm.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;let d={};if(b&&b.classList.contains('js-edit-link')){try{d=JSON.parse(b.dataset.json||'{}')}catch(x){d={}}}document.getElementById('linkTitle').textContent=d.id?'Editar enlace':'Nuevo enlace';const map={linkId:'id',linkCode:'code',linkName:'name',linkFrom:'from_location_id',linkTo:'to_location_id',linkType:'link_type',linkRole:'link_role',linkProvider:'provider',linkCapacity:'capacity_label',linkStatus:'status',linkNotes:'notes'};for(const [el,k] of Object.entries(map))document.getElementById(el).value=d[k]??(el==='linkType'?'utp':el==='linkRole'?'primary':el==='linkStatus'?'unknown':'');document.getElementById('linkMonitored').checked=d.id?!!Number(d.monitored):true;});});
</script><?php endif;?>
